  FU.STAGES = ['Commandé', 'En fabrication', 'Prêt', 'Livré']; FU.OPS = { mat: ['Matière du stock', '🪵'], labor: ['Main-d\'œuvre atelier', '👷'], cost: ['Autre frais', '🧾'] };
  FU.COSTS = ['Tissu / cuir', 'Bois & quincaillerie', 'Sous-traitance', 'Transport', 'Autre']; FU.VISITS = ['Prise de mesures', 'Devis à domicile', 'Livraison', 'Montage', 'Retouche / SAV', 'Autre']; FU.ACTIONS = ['Réparation', 'Échange', 'Remboursement', 'Geste commercial', 'Refusé'];
  FU.CATS = ['Lits & sommiers', 'Matelas & mousse', 'Canapés & fauteuils', 'Armoires & rangement', 'Tables & chaises', 'Cuisine & vaisselier', 'Bureaux', 'Décoration & tapis', 'Literie & linge']; FU.UNITS = ['m³', 'm²', 'matelas', 'set'];
  const orders = () => db().fuOrders, ops = () => db().fuOps, claims = () => db().fuClaims, visits = () => db().fuVisits, packs = () => db().fuPacks, live = o => o.status !== 'Annulé', cur = () => db().settings.currency;
  const rd = (n, c) => M.round(n, c || cur()), num = v => parseFloat(String(v).replace(',', '.')) || 0, main = (o, n) => F.toMain(n, o.currency || cur(), o.rate), nf = S.nf;
  FU.order = id => orders().find(o => o.id === id); FU.op = id => ops().find(o => o.id === id); FU.claim = id => claims().find(c => c.id === id); FU.visit = id => visits().find(v => v.id === id); FU.pack = id => packs().find(p => p.id === id);
  const client = id => db().clients.find(c => c.id === id), cname = id => { const c = client(id); return c ? c.name : 'Client de passage'; }, pname = id => { const p = S.get(id); return p ? p.name : '(supprimé)'; };
