    if (!c.sizes) c.sizes = [['1 place 80×190', 190, 80], ['1 place 90×190', 190, 90], ['1,5 place 120×190', 190, 120], ['2 places 140×190', 190, 140], ['2 places 160×200', 200, 160], ['King 180×200', 200, 180]].map(x => ({ name: x[0], l: x[1], w: x[2] }));
    if (!c.zones) c.zones = [['Centre-ville', 5], ['Périphérie', 10], ['Hors ville', 25]].map(x => ({ name: x[0], fee: x[1] }));
