  FU.foamPrice = f => { const c = FU.cfg(), t = c.foam.find(x => x.name === f.type), vol = (f.l || 0) * (f.w || 0) * (f.t || 0) / 1e6, unit = rd(vol * (t ? t.ppm3 : 0) + (f.l && f.w && f.t ? c.cut : 0) + (f.cover ? c.cover : 0)), qty = f.qty > 0 ? f.qty : 1; return { vol: Math.round(vol * 1e4) / 1e4, unit, qty, total: rd(unit * qty) }; };

  // ---------- derived figures ----------
  const inv = o => { const i = o.invoiceId && A.get(o.invoiceId); return i && A.live(i) ? i : null; };
  FU.opsOf = o => ops().filter(p => p.orderId === o.id && live(p));
