  FU.setStage = (o, stage) => { if (!live(o) || !FU.STAGES.includes(stage) || o.stage === stage) return false; o.stage = stage; (o.stages = o.stages || []).push({ s: stage, date: App.today() }); App.log('furniture.stage', o.number + ' → ' + stage); App.save(); return true; };
