    FU.opsOf(o).forEach(p => FU.cancelOp(p, true)); if (i && A.live(i)) { (i.lines || []).forEach(l => { const p = l.pid && S.get(l.pid); if (p && S.tracked(p)) S.move({ pid: p.id, qty: l.qty, type: 'return', ref: i.number, note: 'Annulation ' + o.number }); }); i.cancelled = true; }
