    const o = FU.order(f.orderId), s = db().settings; if (!o || !live(o) || !FU.OPS[f.type]) return null; const c = f.currency || s.currency, mode = f.mode || s.modes[0], date = f.date || App.today();
    const p = { id: App.uid(), number: A.nextNo('AT', 'at', () => ops()), date, at: Date.now(), type: f.type, orderId: o.id, currency: c, rate: s.rate, mode, note: f.note || '', status: 'Valide' };
    if (f.type === 'mat') { const x = S.get(f.pid); if (!x || !S.tracked(x) || !(f.qty > 0) || f.qty > x.qty + 1e-6) return null; Object.assign(p, { pid: x.id, qty: f.qty, cost: rd(f.qty * (x.cost || 0)) }); p.moveId = (S.move({ pid: x.id, qty: -f.qty, type: 'out', ref: p.number, date, note: 'Atelier · ' + o.number }) || {}).id; }
