    if (R.late) t.push([R.late + ' commande(s) en retard sur la date promise', 'furniture', { tab: 'orders' }]); if (R.ready) t.push([R.ready + ' commande(s) prête(s) à livrer ou à remettre', 'furniture', { tab: 'orders' }]);
    if (R.plans) t.push([R.plans + ' paiement(s) échelonné(s) en retard', 'furniture', { tab: 'orders' }]); if (ag) t.push([ag + ' livraison(s) / rendez-vous aujourd\'hui ou demain', 'furniture', { tab: 'agenda' }]);
